  const now = Date.now();
  return Array.from({length: 60}, (_, i) => ({
    ts: now - (59 - i) * 60_000,
    value: Math.round((Math.sin(i * 0.25) * 15 + 40 + Math.random() * 6) * 10) / 10,
  }));
}

