  sales: makeSalesData(),
  monitor: makeMonitorData(),
};

export function App() {
  return (
    <div style={{padding: 24, maxWidth: 700, margin: '0 auto'}}>
      <ChartWidget data={DEMO_DATA} />
    </div>
  );
}
